(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[177],{1516:function(t,e,n){"use strict";n.r(e),e.default={code:"M1-10",title:"數學規則進階：GCD與應用",tier:"t1",unlockCode:"M1-10-MathGCD",tasks:[{id:"A-09-0",code:"M1-10-A-09-0",title:"判斷質數",description:"質數是大於 1 且只能被 1 和自己整除的數字。\n請寫一個程式，輸入一個整數 N，判斷它是否為質數。\n\n若是質數輸出 Yes，否則輸出 No。\n\n這題訓練你使用條件與迴圈判斷。",examples:[{input:"1",output:"No",explanation:"第一行輸入1\n電腦運算判斷1不是質數\n程式運算輸出No"},{input:"2",output:"Yes",explanation:"第一行輸入2\n電腦運算判斷2是質數\n程式運算輸出Yes"},{input:"7",output:"Yes",explanation:"第一行輸入7\n電腦運算判斷7是質數\n程式運算輸出Yes"},{input:"6",output:"No",explanation:"第一行輸入6\n電腦運算判斷6可被2整除，不是質數\n程式運算輸出No"}],testCases:[{input:"1",expectedOutput:"No",score:10},{input:"2",expectedOutput:"Yes",score:10},{input:"1007",expectedOutput:"No",score:10},{input:"997",expectedOutput:"Yes",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-10-MathGCD/A-09-0.sb3"},{id:"A-09-1",code:"M1-10-A-09-1",title:"找所有因數",description:"因數是指一個整數能被另一整數「整除」時，這個「除數」就是「被除數」的因數。\n\n0不是任何整數的因數。1是所有整數的因數。\n\n請寫一個程式，輸入一個整數 N，請找出N所有的因數。\n\n所有因數以空白符號間格\n\n這題訓練你使用條件與迴圈判斷。",examples:[{input:"12",output:"1 2 3 4 6 12",explanation:"第一行輸入12\n程式輸出12所有因數1 2 3 4 6 12"},{input:"39",output:"1 3 13 39",explanation:"第一行輸入39\n程式輸出39所有因數1 3 13 39"}],testCases:[{input:"56",expectedOutput:"1 2 4 7 8 14 28 56",score:10},{input:"37",expectedOutput:"1 37",score:10},{input:"78",expectedOutput:"1 2 3 6 13 26 39 78",score:10},{input:"88",expectedOutput:"1 2 4 8 11 22 44 88",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-10-MathGCD/A-09-1.sb3"},{id:"A-13-0",code:"M1-10-A-13-0",title:"二個數的最大公因數",description:"小明上學時，不太會找最大公因數，請寫個程式幫他找一下\n輸入二個整數，請計算這二個數字的最大公因數\n輸入格式：輸入2行\n第一行輸入第1個整數N\n第二行輸入地2個整數M\n程式運算找出二數的最大公因數並輸出",examples:[{input:"9\n6",output:"3",explanation:"第一行輸入9，\n第二行輸入6，\n程式輸出6、9二個數的最大公因數3"},{input:"30\n72",output:"6",explanation:"第一行輸入30，\n第二行輸入72\n程式輸出30，72二個數的最大公因數6"}],testCases:[{input:"12\n6",expectedOutput:"6",score:10},{input:"34\n52",expectedOutput:"2",score:10},{input:"24\n18",expectedOutput:"6",score:10},{input:"1\n8",expectedOutput:"1",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-10-MathGCD/A-13-0.sb3"},{id:"TYTN-03",code:"M1-10-TYTN-03",title:"質數和",description:"請輸入兩個 100 以內的正整數（由小到大），找出這兩個數之間所有的質數，並計算這些質數的總和。\n質數定義：大於 1 的整數，除了 1 與本身外沒有其他因數。\n埃拉托賽尼篩法（示意 100 以內）：\n1. 刪除 1（1 不是質數也不是合數）\n2. 2 是質數，刪除大於 2 的所有 2 的倍數\n3. 3 是質數，刪除大於 3 的所有 3 的倍數\n4. 5 是質數，刪除大於 5 的所有 5 的倍數\n5. 7 是質數，刪除大於 7 的所有 7 的倍數\n最後留下的數即為質數",examples:[{input:"21\n30",output:"52",explanation:"21～30 的質數為 23、29\n總和為 52。"},{input:"13\n19",output:"49",explanation:"13～19 的質數為 13、17、19\n總和為 49。"},{input:"54\n58",output:"0",explanation:"54～58 間沒有質數\n因此輸出 0。"}],testCases:[{input:"21\n30",expectedOutput:"52",score:10},{input:"13\n19",expectedOutput:"49",score:10},{input:"54\n58",expectedOutput:"0",score:10},{input:"2\n10",expectedOutput:"17",score:10},{input:"37\n41",expectedOutput:"78",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-10-MathGCD/TYTN-03.sb3"},{id:"cyjunior-007",code:"M1-10-cyjunior-007",title:"校園密室逃脫-費氏階梯(6-2)",description:"電子鐵門開啟後，映入眼簾的是一座懸浮的螺旋階梯，通往二樓的平台。階梯旁懸掛著一張發光的警示牌：「欲登智慧之巔，步法須合天道。或是步履穩健走一階，或是大步流星跨兩階，切勿貪快。」\n小明看著眼前這 N 階的樓梯，不禁開始思考：如果依照規則，每次只能選擇走 1 階或走 2 階，那麼要安全走到第 N 階平台，總共有多少種不同的步伐組合？這正是經典的費氏數列問題，若可能的走法數為F(N)種，我們可觀察到\nF(1)=1               ,1階樓梯有 1種走法\nF(2)=2               ,2階樓梯有 2種走法\nF(3)=F(2)+F(1)=1+2=3 ,3階樓梯有 3種走法\nF(4)=F(3)+F(2)=3+2=5 ,4階樓梯有 5種走法\n…\n請你幫小明計算出所有可能的走法總數",examples:[{input:"3",output:"3",explanation:"走法：(1,1,1), (1,2), (2,1) 共 3 種。"},{input:"4",output:"5",explanation:"走法：(1,1,1,1), (1,1,2), (1,2,1), (2,1,1), (2,2) 共 5 種。"}],testCases:[{input:"1",expectedOutput:"1",score:10},{input:"5",expectedOutput:"8",score:15},{input:"10",expectedOutput:"89",score:20},{input:"15",expectedOutput:"987",score:25},{input:"20",expectedOutput:"10946",score:30}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M1-10-MathGCD/cyjunior-007.sb3"},{id:"A-13-1",code:"M1-10-A-13-1",title:"數列的最大公因數",description:"小明上學時，不太會找最大公因數，請寫個程式幫他找一下\n輸入一組整數，請計算這些數字的最大公因數\n輸入格式：輸入2行\n第一行輸入1個整數N，代表接下來要計算最大公因數的個數\n第二行輸入N個整數，用空格隔開，代表要計算最大公因數的N個整數",examples:[{input:"2\n6 9",output:"3",explanation:"第一行輸入2，表示接下來要輸入2個數\n第二行輸入6 9，表示要找出6、9的最大公因數\n程式輸出最大公因數3"},{input:"3\n4 6 12",output:"2",explanation:"第一行輸入3，表示接下來要輸入3個數\n第二行輸入4 6 12，表示要找出4、6、12的最大公因數\n程式輸出最大公因數2"},{input:"2\n1 99",output:"1",explanation:"第一行輸入2，表示接下來要輸入2個數\n第二行輸入1 99，表示要找出1，99的最大公因數\n程式輸出最大公因數1"},{input:"1\n8",output:"8",explanation:"第一行輸入1，表示接下來要輸入1個數\n第二行輸入8，表示要找出8的最大公因數\n自己的最大公因數是自己，程式輸出最大公因數8"}],testCases:[{input:"3\n12 24 30",expectedOutput:"6",score:10},{input:"6\n2 5 24 15 36 54",expectedOutput:"1",score:10},{input:"3\n51 9 24",expectedOutput:"3",score:10},{input:"1\n8",expectedOutput:"8",score:10}],difficulty:"L4",difficultyLabel:"L4｜精熟",sb3Path:"m0/M1-10-MathGCD/A-13-1.sb3"}]}}}]);